-- ============================================================
-- IMAGO — locales/base/data/snippets.lua (enUS fallback)
-- ============================================================

IMAGO.LoreSnippets["BEHIND_THE_SCENES"] = {
    { text = "Blizzard often makes important lore figures physically larger than they truly are to make them stand out during important gameplay moments."},
    { text = "Blizzard developed a point-and-click adventure game featuring Thrall as he escaped Durnholde Keep and united the Horde. It was scrapped since it didn't meet Blizzard's standard of quality."},
    { text = "World of Warcraft's game editor tool has more lines of code than the programming of the Space Shuttle."},
    { text = "World of Warcraft accounted for 10% of global Internet bandwidth in 2004."},
    { text = "There used to be a small island off the coast of Teldrassil called \"GM Island\", where it was rumored that Game Masters did their work. It was removed from the game after too many players used exploits to explore it."},
    { text = "Instanced dungeons were almost not implemented into the game. The developers worried that it was an antisocial activity that cut players off from the rest of the playerbase."},
    { text = "Dungeons were originally planned to be procedurally generated, but this was abandoned after test runs showed them to be repetitive and forgettable."},
    { text = "The first enemies implemented in World of Warcraft were ogres, kobolds, gnolls, and ghouls."},
    { text = "Before the lore was established, developers kept referring to the Forsaken as the Scourge, despite the creative director's repeated corrections that there was a distinct difference."},
    { text = "Of all the MMOs studied during World of Warcraft's creation, the developers played and analyzed Dark Age of Camelot the most."},
    { text = "There was a planned dungeon for the Barrens with a \"Wild West\" theme, but it was cut since the Barrens had so many dungeons already."},
    { text = "Demons and naga were planned to be playable races, but they were scrapped due to technical reasons."},
    { text = "Before in-house tools were completed, Blizzard loaded their early caves and dungeons into Quake III for playtesting."},
    { text = "Instead of mounts, Tauren were originally intended to run quickly with an ability called Plainsrunning."},
    { text = "Blizzard gives its developers a sword for their fifth year working at the company, and a shield after working for ten years."},
    { text = "Despite having a canon location in previous games, developers were unsure where to put the Dark Portal in World of Warcraft. They first put it on Teldrassil, then they moved it to Azshara. They settled on the Blasted Lands since it had no other interesting landmarks."},
    { text = "The Barrens is among the developers' least favorite zones."},
    { text = "A lot of bushes are actually trees shoved into the ground."},
    { text = "The rogue class was originally called the assassin."},
    { text = "Cut damage types include Mind and Chaos damage."},
    { text = "Environmental fire hazards can harm characters because they are set to \"Hated\" reputation with all players."},
    { text = "One of World of Warcraft's major selling points, quests, was an accident. They intended quests to show players new areas to grind monsters, but they proved so popular that they expanded quests to be the main levelling focus."},
    { text = "At one point in development, World of Warcraft's game engine was converted from imperial units to metric. The change caused all assets to scale incorrectly, and player characters towered like giants."},
    { text = "For a few weeks in development, Stormwind's music was set to Jefferson Starship's pop song, \"We Built This City\". It was removed after it annoyed testers enough that they avoided the city altogether."},
    { text = "Movement speed was originally going to affect stealth—the faster you moved, the easier you were to detect."},
    { text = "Warrior, Mage, and Shaman were the first classes implemented into the game."},
    { text = "Capes were almost not implemented into the game, as developers thought players wouldn't like them blocking the view of their armor."},
    { text = "To keep curious playtesters away from unfinished areas of the game, developers placed infernals named \"Guardians of Blizzard\" to instantly kill any character that tried to enter forbidden zones."},
    { text = "World of Warcraft has millions of invisible rabbits strewn all over the world to assist in event scripts. When an NPC turns to face something or a monster throws a spell on a prop, chances are they're targeting a bunny."},
    { text = "Some developers were against having the experience bar in the user interface. They argued that players should focus more on the joy of playing the game rather than focusing on experience gains."},
    { text = "Consultants told Blizzard to censor bones, skulls, and exposed flesh for the Chinese market. Blizzard complied, but later learned that this was intentional disinformation from competitors to slow down WoW's release."},
    { text = "Before release, the game director expected World of Warcraft to have a five-year lifespan."},
    { text = "Scarlet Monastery used to be one single, large dungeon. Blizzard split it up into smaller, separate wings as an experiment to vary dungeon lengths."},
    { text = "Blizzard experimented with ogres as a playable race. They abandoned the idea after no one wanted to make female ogres, so they reused the model and animations for the Gordok Ogre Suit in Dire Maul. This is why ogres have a dance animation."},
    { text = "Floors need to be open and clear for gameplay clarity, so designers put more effort into walls and ceilings. They lament that most players only look at the floor. The next time you're indoors, look up! You never know what details you'll find."},
    { text = "In early builds, players got reduced experience gain if they played too long. After complaints, this system was reworked into the rested xp system. By the numbers, nothing changed at all. It just labelled the original xp rate as a bonus instead of a penalty for non-rested xp."},
    { text = "The pale, ethereal graphics experienced while running around as a ghost were directly inspired by The Lord of the Rings movies."},
    { text = "During beta tests on a PvP server, Alliance players vastly outnumbered the Horde. Developers joked that the human racial bonus was being surrounded by allies all the time."},
    { text = "When a bug prevented boats from moving between Menethil Harbor and Auberdine, Blizzard added \"Captain Placeholder\" to instantly teleport players to the opposite port. The convenient pirate became popular and players lamented his removal when the bug was fixed."},
    { text = "During early raid testing, Blizzard used fan-made DPS meter addons to measure class performance, since they didn't have internal tools with that functionality."},
    { text = "Runemasters were an early concept for a playable class, utilizing runes imprinted on the body to cast magic in melee combat. These design aspects were later implemented into Death Knight and Monk class abilities."},
    { text = "Early versions of Wailing Caverns had a maze section. The fastest route through was marked with a series of mushrooms."},
    { text = "The earliest prototypes of World of Warcraft were built in the Warcraft III engine."},
    { text = "Since player collision is tied to character size, there are some places where tauren can't fit, or gnomes can't reach."},
    { text = "Blizzard developers thought Player vs. Player combat wouldn't be fun, so it wasn't considered until the MMO Asheron's Call proved PvP fun enough to implement."},
    { text = "Blizzard keeps \"Lore Bibles\" full of drawings, maps, facts, and stories, much of which never make it into the game."},
    { text = "Newly-hired Game Masters are given a day on an internal game server to play around and do whatever they want with their GM powers. This lets them learn their capabilities and get temptation out of their system, so they're less inclined to mess around in live servers."},
    { text = "During development, Blizzard considered Star Wars Galaxies and EverQuest as World of Warcraft's primary competitors."},
}

IMAGO.LoreSnippets["FUN_FACT"] = {
    { text = "Spirit Healers are actually rogue Val'kyr." },
    { text = "Nat Pagle once said: 'You can't catch 'em all if you don't cast a line.'" },
    { text = "IMAGO - The Chronicle of the Unforgotten is never finished - only expanded." },
    { text = "Murlocs speak Nerglish." },
    { text = "The Defias Brotherhood was right." },
    { text = "Bolvar Fordragon was the Lich King longer than Arthas Menethil." },
    { text = "The whispers in the Lordaeron throne room are the last conversation between Arthas and his father from Warcraft III. Turn up your ambient volume to hear them for yourself!" },
    { text = "Critters such as seals and boars have been known to explode when repeatedly poked. This phenomenon has mysteriously stopped since the end of the Third War." },
    { text = "Illidan Stormrage wields the Twinblades of Azzinoth. In their original depiction, they had panda faces engraved at the grip." },
    { text = "Many prominent characters are known to smoke tobacco, including King Terenas, Khadgar, Uther the Lightbringer, and Tirion Fordring." },
    { text = "Stratholme has a sign that points which way to go to reach Stranglethorn, despite that region being on the opposite side of the continent." },
    { text = "Dreadsteeds are raised by the stablemaster demon lord Hel'nurath on the planet Xoroth. To his dismay, warlocks keep stealing them in their summoning rituals." },
    { text = "Alleria and Turalyon aren't married despite having been together for over a thousand years." },
    { text = "Goblin Shredders have a picture of Kerrigan from StarCraft: Brood War on their main screen." },
    { text = "Thrall has blue eyes, which is an extremely rare trait among orcs." },
    { text = "Lordaeron is named after Lordain, a human general who played a pivotal role in the Troll Wars nearly 3,000 years ago." },
    { text = "Ogres regularly hold arm wrestling championships. Guard Mol'dar has been the Dire Maul arm wrestling champion for six years running." },
    { text = "Trolls tend to name their cities after their tribe. The Gurubashi built Zul'Gurub, the Amani live in Zul'Aman, the Farraki shelter in Zul'Farrak, and the Drakkari has Zul'Drak." },
    { text = "When it comes to alcoholic drinks, Tirion Fordring recommends Hearthglen Ambrosia." },
    { text = "The Kirin Tor has a compendium of rules and regulations on the use of the polymorph spell. It is hundreds of pages long." },
    { text = "Dragons believe that mortal races use large, ornate shoulder armor to emulate the majestic wings of dragons." },
    { text = "Most clocks in Azeroth are broken, with arms locked in place. They don't accurately tell the time." },
    { text = "The gnome Tigule invented ice cream, and became incredibly rich selling his flagship strawberry flavor." },
    { text = "Stranglekelp was used to make ice cream during the Ahn'Qiraj war effort to help soldiers mitigate the desert heat." },
    { text = "The Forsaken adopted Gutterspeak to prevent other races from listening in on their schemes. It's a modified form of Common that uses bits of Dwarven and Thalassian." },
    { text = "The warlock spell \"Eye of Kilrogg\" is named after Kilrogg Deadeye, former orc chieftain of the Bleeding Hollow clan." },
    { text = "The Dark Portal features two humanoid statues at each side. No one knows who they're supposed to depict." },
    { text = "\"Tauren\" is an anagram for \"nature\"." },
    { text = "The Wailing Caverns got its name from the sound of water rushing through fissures in the ground that sound like eerie, haunting cries." },
    { text = "The ship found in the Deadmines is an Ogre Juggernaught, a common sight during the Second War." },
    { text = "Creatures under the effects of Curse of Tongues are forced to speak in Demonic." },
    { text = "Binary Brew, obtained from the Brew of the Month Club, temporarily grants the ability to speak in binary." },
    { text = "The orcish phrase \"Zug-zug\" means acknowledgement or agreement." },
    { text = "Enemies appear to be lower level while you're drunk." },
    { text = "Forsaken can be healed with the Light, though it comes with intense pain." },
    { text = "Orgrimmar was named after Orgrim Doomhammer, second Warchief of the Horde." },
    { text = "Durotar was named after Thrall's father, Durotan of the Frostwolf Clan." },
    { text = "Saronite, a metal found in Northrend, is the condensed blood of the Old God Yogg-Saron. Prolonged exposure induces madness." },
    { text = "September 30th is Peon Day, where the people of Stormwind and Orgrimmar celebrate the diligent work of the humble peons and peasants of the world." },
    { text = "Despite the fact that he wears plate armor and wields a sword, Anduin Wrynn is considered a priest, not a paladin." },
    { text = "Booty Bay was originally called Blackwater Cove." },
    { text = "Adventurers had to burn a permanent draconic mark on their skin to attune to Blackwing Lair. This branded mark has never been made visible on player models." },
    { text = "Ancient tauren shamans once mistook the earth elemental Princess Therazane as the Earth Mother." },
    { text = "After he was turned to diamond at Old Ironforge, Magni Bronzebeard became too heavy to ride the lifts at Thunder Bluff." },
    { text = "Chen Stormstout calls the Darkspear trolls living in Thunder Bluff \"Blue Tauren\"." },
    { text = "Finely-ground draenei tail is a potent ingredient for necromantic experiments." },
    { text = "Void elves find the chiming noises made by Naaru very irritating." },
    { text = "Despite being known as the 'son of Deathwing', Wrathion is actually his grandson."},
    { text = "Jaina Proudmoore began her studies as a fire mage in Dalaran. After almost burning down the university rooms and Kael'thas Sunstrider by accident, she decided to focus on ice magic instead."},
    { text = "Some animals on Azeroth live normal lives despite missing important organs such as their livers or hearts. While fascinating, this can be frustrating for hunters and gatherers."},
    { text = "Illidan's iconic lines such as 'You are not prepared' or 'I am my scars' have been repeated by adventurers for decades. Illidan is very much aware of this and can be convinced to repeat some of them in an annoyed tone if poked long enough."},
    { text = "Notice how your mail gets delivered even if you left your loot in the most dangerous of places? This feat is accomplished by the Postmaster and a few assistants. They operate from Dalaran and would appreciate a visit."},
    { text = "Phoenixes are not birds but actually elementals. That is why fire mages can summon them."},
    { text = "Despite being named 'Blood Mages', these specific Silvermoon spellcasters use Arcane and Fel magic instead of blood."},
    { text = "The Dalaran Fountain is said to grant wishes for coins thrown into it."},
    { text = "Just like his former mentor Medivh, Archmage Khadgar is said to cheat at chess."},
    { text = "There are rumors going around that a cat named Jenafur roams the haunted halls of Karazhan. Her whispers should be ignored."},
    { text = "Even though he was vaporized by the Sunwell and killed again by Lor'themar Theron, Dar'Khan Drathir somehow reappeared in the Ghostlands shortly before the Blood Elves joined the Horde." },
    { text = "Have you heard of the boy called Me'dan? No? Neither have we." },
    { text = "According to Flynn Fairwind, an expert on the subject, the rum served in Booty Bay tastes far better than its Kul Tiran counterpart." },
    { text = "Despite being blind in his left eye, Lor'themar was occasionally spotted wearing an eye patch over his right eye. If poked about it for long enough, he denies that this mix-up ever happened." },
    { text = "All cats go to Revendreth." },
    { text = "In most other timelines, Garrosh Hellscream was known as one of the best warchiefs the Horde ever had." },
    { text = "If your last name is Windrunner, there is a good chance you are attracted to humans." },
    { text = "Illidan “the Betrayer” Stormrage, never actually betrayed anyone apart from the Burning Legion." },
    { text = "Sylvanas' nickname for King Anduin is “Little Lion”. This is because he reminds her of her younger brother Lirath, who died in the Second War. He was called “Little Lord Sun.”" },
    { text = "The word “cynosure” can't be pronounced correctly." },
    { text = "Zekhan was affectionately dubbed “Zappy Boi” by the community before his name was made public. Blizzard acknowledged the nickname in the book Shadows Rising and had Bwonsamdi call him that." },
    { text = "The Knights of the Silver Hand gave Arator the name “the Redeemer” without knowing what or whom he would one day redeem." },
    { text = "Orcs have better eyesight than humans." },
}

IMAGO.LoreSnippets["DID_YOU_KNOW"] = {
    { text = "Azeroth can refer to five different things: Azeroth the Titan, Azeroth the planet, Azeroth the continent (Eastern Kingdoms), Azeroth the region (south of Khaz Modan), and Azeroth the kingdom (now called the Kingdom of Stormwind)." },
    { text = "Goblins are a failed experiment by Titan Keeper Mimiron." },
    { text = "Duskwood used to be known as Brightwood until the Guardian Medivh's death. The Guardian's death released a wave of fel energy that caused an everlasting night" },
    { text = "Elves are magically evolved trolls." },
    { text = "The Void is not empty, but instead an amalgamation of energy akin to the burning insides of a star. Many have been driven mad by it." },
    { text = "The Wretched are blood elves that succumbed to their addiction to magic, becoming feral and deformed as a result." },
    { text = "Ogres are surprisingly good shipwrights and sailors." },
    { text = "Tartek the Enraged was one of the most powerful Abominations to ever be created. We only know of his existence through a single piece of Scourge literature in the Ebon Hold." },
    { text = "The Wildhammer dwarves are famous for riding gryphons and wielding Stormhammers—enchanted weapons that strike with the force of thunder and lightning when thrown." },
    { text = "The Discs of Norgannon, sometimes referred to as the Platinum Discs, are a wondrous artifact entombed in Uldaman. They are a library of Azeroth's entire history, and new information continues to be recorded within them as they occur." },
    { text = "Obsidian may have the capacity to manipulate mana, as evidenced by the Obsidian Sentinel in Uldaman and the Obsidian Destroyers employed by the Scourge and the Qiraji." },
    { text = "While the forces of the Scarlet Monastery are primarily human, the Scarlet Armory features three statues honoring non-human members of the Scarlet Crusade." },
    { text = "In extremely rare cases, instead of resurrection, the Holy Light will produce an undead animated with Light instead of necromancy." },
    { text = "Demons can only be permanently killed in the Twisting Nether and Naaru can only be permanently killed in the realm of Light. Only exceptionally powerful entities can bypass this restriction." },
    { text = "Kobolds are possessive of their candles because they have a primal fear of the voidwraith called the Devouring Darkness." },
    { text = "Members of the Horde can learn Gnomish Engineering thanks to the gnome Oglethorpe Obnoticus. He was falsely accused for crimes he did not commit and exiled from Gnomeregan, so he teaches the Horde as an act of revenge." },
    { text = "Azeroth has two moons, the White Lady and the Blue Child. Every 430 years, they overlap each other in an event called the Embrace—because it appears as if the \"mother\" is holding her \"child\"." },
    { text = "It's sheer coincidence that the orcish Blackrock clan headquartered in Blackrock Mountain. The clan was named after blackrock ore in Draenor, long before the Horde's invasion of Azeroth." },
    { text = "There once existed a legendary sword called Andonisus, Reaper of Souls. It could only be wielded for up to five minutes during the fight against the demon Atiesh in Stratholme. It would kill its wielder in 20 seconds if not healed." },
    { text = "The leader of the Scarlet Crusade was a demon in disguise." },
    { text = "Despite being allies, the Knights of the Ebon Blade attacked Light's Hope Chapel in hopes of raising Tirion Fordring's corpse as a member of the Four Horsemen. They failed in their endeavor." },
    { text = "Standard Ironforge rations include haggis and beer. It's been a staple for the dwarven military for over a millenium." },
    { text = "The Alliance once set a trap for Thrall in the Stonetalon Mountains where they polymorphed themselves into sheep, ready to ambush. Thrall saw through the ruse, since sheep are not native to Kalimdor." },
    { text = "There is a long-held belief among night elves that those with golden eyes are destined for greatness. Prominent golden-eyed night elves include Queen Azshara and Illidan Stormrage." },
    { text = "The orcish tradition of Mak'gora involves a ritualistic duel to the death to settle disputes, usually for leadership." },
    { text = "Orcs are natively brown. After drinking the corrupted blood of the pit lord Mannoroth, most orc skin turned green." },
    { text = "The road between the Dark Portal and Hellfire Citadel is paved with the bones of thousands of murdered Draenei." },
    { text = "If you listen closely in the throne room at the entrance to the Undercity, you can hear the ghostly whispers of Arthas killing his father." },
    { text = "Tauren hooves have been used as a secret ingredient for candy." },
    { text = "Rogues used to blind opponents using an irritant made from Fadeleaf. Eventually, they stopped doing so, opting to use dirt or sand instead." },
    { text = "The Dark Riders of Deadwind Pass were once a band of travelling merchants who tried to sell fraudulent artifacts to Medivh. Now, they are cursed to forever seek real artifacts and return them to the Guardian." },
    { text = "Silver is heavy, but pretty, and used in jewelry and trinkets. Truesilver is lighter and stronger than steel, so it is more suited for armor and weapons." },
    { text = "The Kirin Tor Tavern Crawl was an event where mages set up portals between various bars and taverns of the world. Participants were encouraged to try something new at each destination." },
    { text = "Wolves in Elwynn Forest can be observed hunting and killing rabbits." },
    { text = "There have been seven Warchiefs of the Horde: Blackhand the Destroyer, Orgrim Doomhammer, Ner'zhul, Thrall, Garrosh Hellscream, Vol'jin, and Sylvanas Windrunner. Now, it is ruled by a council of leaders." },
    { text = "The Sunwell used to have a human manifestation named Anveena Teague." },
    { text = "There are at least six derivative dragonflights that are corrupted or experimental offshoots of the main five." },
    { text = "Slavery is still legal in most nations of the Horde and the Alliance, despite the factions' former leaders Thrall and Varian being freed slaves themselves."},
    { text = "Most members of the blue dragonflight only exist today because the red dragon Korialstrasz meddled with the timeways during the War of the Ancients. Instead of letting the abandoned eggs of Malygos wither away as he was supposed to, he instead saved their lives."},
    { text = "At one point or another in time, the Champions of Azeroth have fought and killed every one of the original Dragon Aspects except for Alexstrasza."},
    { text = "Dragons are inherently polyamorous. For the longest time, Alexstrasza had four consorts at once."},
    { text = "Grand Magister Rommath was supposed become a villain during the Cataclysm expansion as a traitor for the Twilight's Hammer. This was changed last minute and the role was given to Archbishop Benedictus, even though Rommath's voice lines were already recorded."},
    { text = "Paladins traditionally name their horses after virtues they follow. Prominent examples are Uther's horse 'Steadfast', Arthas' steed 'Invincible', and Anduin's companion 'Reverence'."},
    { text = "Have you heard the tales and songs about Azeroth from the Hearthstone Inn? Take a seat, warm your boots by the fire and have a listen and a laugh. The Inn is always open to everyone."},
    { text = "Stormwind's spymaster Mathias Shaw once snuck into the Undercity through the front entrance. He does not elaborate how he managed that."},
    { text = "The orc shaman Ner'zhul mastered four of the six cosmic forces: Life - as a shaman, Fel – as a warlock, Arcane – when shattering Draenor, and Death – as the Lich King. His alternate version in the Iron Horde wielded the Void as well."},
    { text = "Various races from Azeroth and beyond are able to reproduce despite having no shared genetic heritage such as elves and humans, or orcs and draenei."},
    { text = "Thrall's mother tongue is common. He began learning orcish as a teenager and has since lost his accent."},
    { text = "The Rift of Aln has bled into the Twisting Nether itself. This is not common knowledge, as the Rift is mostly associated with the Emerald Dream."},
    { text = "Medivh was the only human Deathwing considered worthy of his respect." },
    { text = "The word “Draenei” means “Exiled Ones”." },
    { text = "Garrosh Hellscream is the only person known to have fought three Mak'goras." },
    { text = "The Elite Tauren Chieftains are a famous group of heavy metal musicians in Azeroth. They perform regularly at the Darkmoon Faire." },
    { text = "The only two dragons to have ever officially been part of the two factions are Ebyssian, as Spiritwalker of the Highmountain Tauren, and Korialstrasz, as an Archmage of Dalaran when the magocracy was still part of the Alliance." },
    { text = "Zovaal, the Jailer, has domination runes carved into his body, even though he wouldn't need them to dominate his victims." },
    { text = "Most human royals live in arranged marriages. Genn and Mia Greymane are a rare exception and had married for love." },
    { text = "Talanji was the only racial leader of the Horde to neither join Sylvanas or Saurfang during the Horde's leadership crisis at the end of the Fourth War." },
    { text = "Liches, such as the mage Kel'Thuzad, can infinitely come back to life as long as their phylacteries remain intact." },
    { text = "Most Forsaken change their names to distinguish themselves from the people they once were. Nathanos Blightcaller, for example, was once called Nathanos Marris." },
    { text = "The arrakoan name for Draenor is Rakshar." },
    { text = "Both Mannoroth and Illidan Stormrage recognized Queen Azshara as a more powerful spellcaster than themselves." },
    { text = "The ghosts of the carnies of the Darkmoon Faire are perpetually bound to the island. Some claim to have been with the Faire for centuries." },
    { text = "The famous phrase “Lok'tar Ogar” means “Victory or Death” in orcish." },
    { text = "During the War against the Nightmare, a strange mist covered most of the lands and prevented people from waking up. It was the first time Xavius proved how much of a threat the Emerald Nightmare could pose to the waking world." },
    { text = "Faerin Lothar is not a cat person and is one of the few Hallowfall Arathi to not ride a lynx mount." },
    { text = "Once per year, the Champions of Azeroth can volunteer to take an orphaned child under their wing for a week to show them the world and adventure together. It means everything to many of these kids." },
    { text = "Varian Wrynn and Arthas Menethil grew up and trained together." },
}

IMAGO.LoreSnippets["HISTORICAL_FACT"] = {
    { text = "The feared C'thraxxi creature named Kith'ix was a general for the Old Gods thousands of years ago. He was defeated and buried in Zul'Aman, where his body remains to this day." },
    { text = "Dath'remar Sunstrider founded Quel'Thalas after the War of the Ancients. His statue can be found on Sunstrider Isle." },
    { text = "The Radiant Song was heard not only on Azeroth, but also on the faraway world of K'aresh, shortly before it was destroyed." },
    { text = "The Dead Scar was almost completely healed by the Sunwell. Nowadays few traces of Arthas' invasion remain visible in Silvermoon." },
    { text = "The Defias Brotherhood was originally founded after the Kingdom of Stormwind refused to pay the stonemasons for their work in the reconstruction of Stormwind." },
    { text = "The Sunwell is roughly 7,000 years old." },
    { text = "Stormwind City was founded roughly 1,200 years before the First War. By Midnight, the city is physically ancient, but most of its visible infrastructure is rebuilt from the past 30-40 years of in-universe history." },
    { text = "Halduron Brightwing is the first Ranger-General of Silvermoon who isn't a Windrunner in at least three generations." },
    { text = "The orc Broxigar used an enchanted wooden axe to slice through the leg of Sargeras. He is one of the few mortals known to have injured the Titan." },
    { text = "Tanaris was once a lush jungle until the Great Sundering shattered the world and disrupted the climate." },
    { text = "The first paladins were created during the Second War to counteract the dark magic of the Horde. It was a mishmash of priests given military training and knights ordered to study holy books, but the desperate measure worked." },
    { text = "75 years before the First War, the Kingdom of Stormwind was nearly destroyed by gnolls." },
    { text = "The thorny vines that make up Razorfen Kraul and Razorfen Downs are the remains of the demigod Agamaggan, the Razorboar. He fell in battle against the Burning Legion during the War of the Ancients." },
    { text = "Gnomes were absent during the Third War because Gnomeregan was besieged by troggs at the time." },
    { text = "Humans discovered the holy powers of the Light around 3,000 years ago during the Troll Wars. Mereldar was the first human priestess to invoke its healing power." },
    { text = "Around 250 years ago, Dark Iron Sorcerer-Thane Thaurissan attempted to summon Ragnaros the Firelord to destroy his enemies. The resulting devastation killed him and created Blackrock Mountain." },
    { text = "Two-headed ogres were created during the Second War, when Gul'dan converted ancient elven runestones into structures called an Altar of Storms." },
    { text = "During the Second War, the King Perenolde of Alterac lost hope and switched sides to ally with the Horde. The Alliance destroyed Alterac in retaliation for this betrayal." },
    { text = "The Lunar Festival celebrates the end of the War of the Ancients, where the races of Azeroth repelled the Burning Legion invasion ten thousand years ago." },
    { text = "During the Second War, the orc Nekros Skullcrusher captured Alexstrasza and forced her children to fight on behalf of the Horde." },
    { text = "Ancient Draenor was covered in a hivemind of plants and fungus called the Evergrowth. It was destroyed when ancient Arakkoa activated a superweapon that used solar energy to devastating effect." },
    { text = "Around 2,600 years ago, the first Guardian of Tirisfal was created. They were mages imbued with immense power and the responsibility to defend Azeroth from demon invasion." },
    { text = "After the First War, the event was declared so significant that the calendar was reset. Year 0 marked when the Horde invaded Azeroth for the first time." },
    { text = "There exists a \"one true timeline\", and the Bronze Dragonflight is dedicated to its preservation." },
    { text = "Kalimdor used to refer to the entire giant landmass that existed before the Sundering split it apart into the continents we know today."},
    { text = "The Zandalari Empire is the oldest nation on Azeroth, having existed for over 16,000 years."},
    { text = "Legends state that the first world tree, Elun'ahir, was ripped out of the earth by the titan Aman'Thul during the war against the Black Empire. The roots are said to have survived, but no trace has been found of them as of yet."},
    { text = "The only Old God that is considered fully dead is Y'Shaarj. He was killed by Aman'Thul, but his death caused much damage to Azeroth, and thus the other Old Gods were merely imprisoned."},
    { text = "There exist four Old Gods: Y'Shaarj, N'Zoth, Yogg-Saron, and C'Thun. However, there is some older literature that refers to the existence of a fifth Old God."},
    { text = "The Dark Heart is a prototype of the Dragon Soul."},
    { text = "Silvermoon used to be adorned with many statues of its leader, Kael'thas Sunstrider. Following his betrayal, all of them were destroyed or dumped in the harbor."},
    { text = "Before settling on Azeroth, the draenei tried to hide from the Legion on many other planets, including Draenor and Naigtal."},
    { text = "The Burning Legion tried to create the Scourge for thousands of years, but without the Lich King, they were unsuccessful. Crude attempts at using the living dead as a weapon have been witnessed during the War of the Ancients."},
    { text = "Maiev once tried to murder Malfurion."},
    { text = "The Elemental Lords were subdued when the Old Gods came to Azeroth, and served as their lieutenants. Some, like Ragnaros the Firelord, stayed loyal even long after the Black Empire had fallen."},
    { text = "The Elemental Plane consists of four interlinked domains – the Firelands, Skywall, the Abyssal Maw, and Deepholm. It is an artificial titan-made pocket dimension, meant to imprison Azeroth's elements."},
    { text = "The first death knights were created by Gul'dan when he transferred the souls of orcish warlocks into the corpses of fallen Alliance heroes. Teron Gorefiend was the first death knight in existence." },
    { text = "Malfurion was once so filled with grief that his tears manifested as a heavy rain that almost drowned the entire night elven army." },
    { text = "Many of Stormwind's war veterans who were unable to care for themselves ended up in Westfall - the poorest corner of the kingdom." },
    { text = "When Sargeras first laid eyes on Azeroth's world-soul, he became infatuated." },
    { text = "The Worgen were created on Kalimdor during the War of the Satyr when the desperate night elven druids fought against their corrupted kin. The attempt to transform into a new form led these Druids of the Scythe to become aggressive and volatile, and the practice was outlawed by the Cenarion Circle." },
    { text = "In an attempt to shield their homeworld of K'aresh, the ethereals lost their physical bodies completely. In the end, K'aresh fell to Dimensius and the world's people were forced to roam both the physical universe and the realms of death." },
    { text = "The Sisterhood of Elune used to, as the name implies, only allow women and girls to join their ranks. This has changed in recent years." },
    { text = "Deathwing's name is a paradox. During the War of the Ancients, the time-traveling dragon Korialstrasz called Neltharion by his future moniker. The other Aspects thought it fitting and adopted it. So even though Korialstrasz originally heard the name Deathwing from the Aspects, he now was the reason they knew it in the first place." },
    { text = "Bwonsamdi, Loa of the Graves, was a mortal hash'ey before becoming a god." },
    { text = "Every four hundred and thirty years, the two moons of Azeroth align perfectly in an event called “the Embrace“." },
    { text = "The only orcs on Draenor who did not drink Mannoroth's blood were the Frostwolf Clan, the sick of Garadar, Orgrim Doomhammer and Ner'zhul." },
    { text = "Before Queen Azshara conquered them, the Zandalari Empire ruled over almost all of ancient Kalimdor." },
    { text = "According to the bronze dragon Soridormi, the Battle of Mount Hyjal during the Third War is one of the most well-guarded events of the timeline on Azeroth." },
    { text = "The element of life is much weaker than the other elements on Azeroth. On Draenor, where all elements are equal in strength, the dangerous rapid growth of the Everbloom demonstrates the difference well." },
    { text = "The titans Sargeras and Aggramar used to be friends. They fought side by side against the demons and the Void until Sargeras' great betrayal." },
    { text = "Humans, dwarves, gnomes and many other races on Azeroth only exist because the Old Gods' Curse of Flesh gave them free will and a mortal body." },
    { text = "Re-origination is the titanic practice of purging all life from a planet, mostly as a last resort against systemic Void corruption. During the War against the Lich King, Azeroth was set to be re-originated. The heroes who fought in Ulduar managed to sway the titan servant Algalon at the last moment." },
    { text = "The cosmic being Murmur was born in a far-away corner of the cosmos unfathomable to mortal minds. His mere whisper was powerful enough to destroy entire worlds in an instant." },
    { text = "Even long after Draenor was shattered and became Outland, many of Ner'zhul's portals remained open and served the Legion as tools to strengthen their hold on the doomed world." },
}
